INSERT INTO people (id, slug, name, role, description, born, died) VALUES (1, 'lemnitzer', 'Lyman L. Lemnitzer', 'Chairman of the Joint Chiefs of Staff (1960–1962)', 'U.S. Army general who signed the Operation Northwoods memorandum as chairman of the Joint Chiefs.', '1899', '1988');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (2, 'gottlieb', 'Sidney Gottlieb', 'CIA chemist', 'Head of the CIA chemical division that ran the MKUltra program.', '1918', '1999');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (3, 'helms', 'Richard Helms', 'Director of Central Intelligence (1966–1973)', 'CIA director who ordered the destruction of MKUltra records in 1973.', '1913', '2002');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (4, 'olson', 'Frank Olson', 'U.S. Army scientist', 'Scientist who died in November 1953, days after being given LSD without his knowledge in a CIA experiment.', '1910', '1953');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (5, 'nixon', 'Richard Nixon', '37th President of the United States', 'Resigned from office on 9 August 1974 as a result of the Watergate scandal.', '1913', '1994');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (6, 'felt', 'W. Mark Felt', 'FBI Associate Director', 'Identified himself in 2005 as ''Deep Throat'', the confidential source of The Washington Post.', '1913', '2008');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (7, 'kennedy', 'John F. Kennedy', '35th President of the United States', 'Assassinated in Dallas on 22 November 1963.', '1917', '1963');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (8, 'oswald', 'Lee Harvey Oswald', 'Accused assassin', 'Named by the Warren Commission as the assassin of President Kennedy; shot and killed by Jack Ruby on 24 November 1963.', '1939', '1963');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (9, 'weishaupt', 'Adam Weishaupt', 'Founder of the Illuminati', 'Professor of canon law at the University of Ingolstadt who founded the Order of the Illuminati in 1776.', '1748', '1830');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (10, 'barruel', 'Augustin Barruel', 'Jesuit priest and author', 'Author of a multi-volume work (1797–1798) that blamed the French Revolution on a conspiracy including the Illuminati.', '1741', '1820');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (11, 'robison', 'John Robison', 'Physicist and author', 'Scottish physicist whose ''Proofs of a Conspiracy'' (1797) made similar claims about the Illuminati and Freemasonry.', '1739', '1805');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (12, 'lazar', 'Bob Lazar', 'Claimant', 'Claimed in 1989 to have worked on extraterrestrial spacecraft at a site near Area 51. His claims are unverified.', '1959', NULL);
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (13, 'armstrong', 'Neil Armstrong', 'Apollo 11 commander', 'First person to walk on the Moon, on 20 July 1969 (UTC: 21 July).', '1930', '2012');
INSERT INTO people (id, slug, name, role, description, born, died) VALUES (14, 'kaysing', 'Bill Kaysing', 'Author', 'Author of ''We Never Went to the Moon'' (1976), an early publication of the Moon landing hoax claim.', '1922', '2005');
