INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (1, 'operation-northwoods', 'Operation Northwoods', 'A documented 1962 proposal for staged pretexts against Cuba', 'In March 1962 the U.S. Joint Chiefs of Staff proposed staging or simulating attacks that could be blamed on Cuba in order to justify a military intervention. The proposal is documented in a declassified memorandum. It was not approved by the civilian leadership and was never carried out.', 'After the failed Bay of Pigs invasion (April 1961) the Kennedy administration pursued covert pressure on the Cuban government under Operation Mongoose. Within this context the Joint Chiefs of Staff forwarded a set of pretext proposals to Secretary of Defense Robert McNamara.', 'The memorandum was declassified in 1997 by the Assassination Records Review Board as part of the review of records related to the Kennedy assassination. It became widely known after James Bamford described it in "Body of Secrets" (2001) and the National Security Archive published it online.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After the failed Bay of Pigs invasion (April 1961) the Kennedy administration pursued covert pressure on the Cuban government under Operation Mongoose. Within this context the Joint Chiefs of Staff forwarded a set of pretext proposals to Secretary of Defense Robert McNamara."}]},{"type":"paragraph","content":[{"type":"text","text":"The memorandum was declassified in 1997 by the Assassination Records Review Board as part of the review of records related to the Kennedy assassination. It became widely known after James Bamford described it in \"Body of Secrets\" (2001) and the National Security Archive published it online."}]}]}', 10, 'historically_documented', '/media/cards/document.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:00');
