INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (1, 1, 'The Joint Chiefs of Staff sent a memorandum titled "Justification for US Military Intervention in Cuba" to the Secretary of Defense on 13 March 1962.', 'historically_documented', 0);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (1, 1, 1, 1, 'documents');
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (2, 2, 1, 1, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (2, 1, 'The proposals included staged incidents such as a simulated attack on a U.S. ship, fabricated incidents blamed on Cuba, and a staged "Remember the Maine" incident.', 'historically_documented', 1);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (3, 1, 1, 2, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (3, 1, 'The plan was approved and carried out.', 'debunked', 2);
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (1, 1, 3, 'No document or testimony shows that any of the Northwoods proposals were implemented; the civilian leadership did not approve them.', 0);
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (4, 2, 1, 1, 'refutes');
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (5, 3, 1, 1, 'refutes');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (4, 1, 'Northwoods proves that later disasters were "false flag" operations staged by the U.S. government.', 'unverified', 3);
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (2, 1, 4, 'A rejected 1962 proposal is not evidence about any other event. Each such claim needs its own independent evidence.', 1);
INSERT INTO evidence (id, source_id, theory_id, relation, note) VALUES (6, 4, 1, 'context', 'The memorandum was released through the JFK records review.');
INSERT INTO evidence (id, source_id, theory_id, relation, note) VALUES (7, 3, 1, 'context', NULL);
INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (2, 'mkultra', 'MKUltra', 'The CIA''s covert program of behavioral modification research', 'MKUltra was a CIA research program, approved in 1953, that investigated drugs and other methods to influence human behavior, including experiments on people who had not given their consent. Its existence was confirmed by official investigations in the 1970s. Most of its records were destroyed in 1973.', 'During the early Cold War, U.S. agencies feared that adversaries had developed interrogation and "brainwashing" techniques. The CIA funded research at universities, hospitals and prisons, often through front organizations, under a series of code-named projects of which MKUltra is the best known.', 'Public knowledge began with the Rockefeller Commission (1975) and the Church Committee (1975–1976). In 1977 about 20,000 surviving financial records were found and discussed at a Senate hearing.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"During the early Cold War, U.S. agencies feared that adversaries had developed interrogation and \"brainwashing\" techniques. The CIA funded research at universities, hospitals and prisons, often through front organizations, under a series of code-named projects of which MKUltra is the best known."}]},{"type":"paragraph","content":[{"type":"text","text":"Public knowledge began with the Rockefeller Commission (1975) and the Church Committee (1975–1976). In 1977 about 20,000 surviving financial records were found and discussed at a Senate hearing."}]}]}', 3, 'historically_documented', '/media/cards/agency.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:01');
