INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (3, 'watergate', 'Watergate', 'A documented political conspiracy that ended a presidency', 'The 1972 break-in at the Democratic National Committee offices in the Watergate complex and the subsequent cover-up led to President Richard Nixon''s resignation in August 1974. Watergate is a political conspiracy established by courts, Congress and the recorded White House tapes.', 'During the 1972 presidential campaign, operatives linked to the Committee for the Re-Election of the President conducted espionage and sabotage against political opponents. The arrest of five burglars on 17 June 1972 began investigations by journalists, a special prosecutor, a federal grand jury and the Senate.', 'Reporting by The Washington Post, the televised Senate hearings of 1973 and the disclosure of Nixon''s secret taping system turned the break-in into a constitutional crisis.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"During the 1972 presidential campaign, operatives linked to the Committee for the Re-Election of the President conducted espionage and sabotage against political opponents. The arrest of five burglars on 17 June 1972 began investigations by journalists, a special prosecutor, a federal grand jury and the Senate."}]},{"type":"paragraph","content":[{"type":"text","text":"Reporting by The Washington Post, the televised Senate hearings of 1973 and the disclosure of Nixon''s secret taping system turned the break-in into a constitutional crisis."}]}]}', 1, 'historically_documented', '/media/cards/document.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:02');
