INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (4, 'area-51', 'Area 51', 'A real secret test site and the extraterrestrial claims around it', 'Area 51 at Groom Lake, Nevada, is a real and long-secret test facility used to develop reconnaissance aircraft such as the U-2 and the A-12 OXCART; its existence was officially acknowledged in 2013. Claims that it holds or studies extraterrestrial spacecraft remain unverified.', 'In 1955 the CIA and the Air Force selected the remote dry lake bed at Groom Lake as a testing site for the U-2 spy plane. Later programs, including the A-12 OXCART, were also tested there. Strict secrecy around the base encouraged speculation.', 'The extraterrestrial narrative gained wide attention in 1989, when Bob Lazar claimed in a Las Vegas television interview that he had worked on alien craft at a nearby site called "S-4".', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In 1955 the CIA and the Air Force selected the remote dry lake bed at Groom Lake as a testing site for the U-2 spy plane. Later programs, including the A-12 OXCART, were also tested there. Strict secrecy around the base encouraged speculation."}]},{"type":"paragraph","content":[{"type":"text","text":"The extraterrestrial narrative gained wide attention in 1989, when Bob Lazar claimed in a Las Vegas television interview that he had worked on alien craft at a nearby site called \"S-4\"."}]}]}', 4, 'unverified', '/media/cards/location.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:03');
