INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (15, 4, 'A secret test site at Groom Lake, Nevada, was used by the CIA and the Air Force to develop and test reconnaissance aircraft such as the U-2 and the A-12 OXCART.', 'historically_documented', 0);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (25, 16, 4, 15, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (16, 4, 'The U.S. government officially acknowledged the site in 2013 through the release of a declassified CIA history.', 'historically_documented', 1);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (26, 16, 4, 16, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (17, 4, 'Secret high-altitude reconnaissance flights explain a significant number of UFO reports from the 1950s and 1960s.', 'supported_by_evidence', 2);
