INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (5, 4, 18, 'No verifiable evidence has been produced. A 2024 Department of Defense review found no evidence that any U.S. government program had extraterrestrial technology. Claimed academic credentials of the best-known witness could not be confirmed.', 0);
