INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (5, 'moon-landing-conspiracy-theory', 'Moon Landing Conspiracy Theory', 'The claim that the Apollo landings were faked', 'The claim that NASA staged the Apollo Moon landings (1969–1972) appeared in the 1970s. It is contradicted by extensive independent evidence, including returned lunar samples, retroreflectors still used for laser ranging, independent tracking of the missions and orbital images of the landing sites.', 'Between 1969 and 1972 six Apollo missions landed twelve astronauts on the Moon. The program took place during the Cold War space race with the Soviet Union, which tracked the missions closely.', 'Bill Kaysing''s self-published book "We Never Went to the Moon" (1976) is one of the earliest publications of the claim. Television documentaries and, later, online videos spread it further.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Between 1969 and 1972 six Apollo missions landed twelve astronauts on the Moon. The program took place during the Cold War space race with the Soviet Union, which tracked the missions closely."}]},{"type":"paragraph","content":[{"type":"text","text":"Bill Kaysing''s self-published book \"We Never Went to the Moon\" (1976) is one of the earliest publications of the claim. Television documentaries and, later, online videos spread it further."}]}]}', 4, 'debunked', '/media/cards/technology.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:04');
