INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (31, 20, 5, 19, 'documents');
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (32, 22, 5, 19, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (20, 5, 'The Moon landings were staged in a studio.', 'debunked', 1);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (33, 24, 5, 20, 'context');
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (6, 5, 20, 'Retroreflectors placed by Apollo crews are still used for laser ranging, lunar samples have been studied by scientists worldwide, and orbital cameras have photographed the landing hardware and astronaut tracks.', 0);
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (34, 23, 5, 6, 'refutes');
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (35, 21, 5, 6, 'refutes');
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (36, 22, 5, 6, 'refutes');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (21, 5, 'Photographs show inconsistencies (no stars, a "waving" flag, non-parallel shadows) that prove fakery.', 'debunked', 2);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (37, 24, 5, 21, 'context');
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (7, 5, 21, 'Short camera exposures for the bright lunar surface do not capture faint stars; the flag was held by a horizontal rod and moved only when handled; shadows diverge because of perspective and uneven terrain.', 1);
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (38, 22, 5, 7, 'refutes');
INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (6, 'illuminati-narratives', 'Illuminati Narratives', 'From an 18th-century Bavarian society to a global myth', 'The Order of the Illuminati was a real Enlightenment-era secret society founded in Bavaria in 1776 and suppressed by 1785. Claims that it survived and secretly controls world events are not supported by evidence.', 'Adam Weishaupt, a professor at the University of Ingolstadt, founded the order to promote Enlightenment ideas against the influence of the church and absolutism. It recruited among the educated elite, partly through Masonic lodges, before Elector Karl Theodor banned unauthorized secret societies.', 'After the French Revolution, Augustin Barruel and John Robison (both 1797) blamed the revolution on a conspiracy involving the Illuminati. Variants of this narrative have circulated ever since and frequently overlap with antisemitic conspiracy myths.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Adam Weishaupt, a professor at the University of Ingolstadt, founded the order to promote Enlightenment ideas against the influence of the church and absolutism. It recruited among the educated elite, partly through Masonic lodges, before Elector Karl Theodor banned unauthorized secret societies."}]},{"type":"paragraph","content":[{"type":"text","text":"After the French Revolution, Augustin Barruel and John Robison (both 1797) blamed the revolution on a conspiracy involving the Illuminati. Variants of this narrative have circulated ever since and frequently overlap with antisemitic conspiracy myths."}]}]}', 2, 'unverified', '/media/cards/organization.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:05');
