INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (22, 6, 'The Order of the Illuminati was founded in Ingolstadt, Bavaria, on 1 May 1776 by Adam Weishaupt.', 'historically_documented', 0);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (39, 25, 6, 22, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (23, 6, 'The order was suppressed by edicts of the Bavarian Elector Karl Theodor in 1784 and 1785.', 'historically_documented', 1);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (40, 25, 6, 23, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (24, 6, 'The Illuminati secretly survived and orchestrated the French Revolution.', 'unverified', 2);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (41, 26, 6, 24, 'context');
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (42, 27, 6, 24, 'context');
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (8, 6, 24, 'Historians have found no evidence that the order remained active after its suppression. The French Revolution has extensively documented political, social and economic causes.', 0);
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (43, 25, 6, 8, 'refutes');
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (44, 28, 6, 8, 'refutes');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (25, 6, 'The Illuminati control governments, finance or the entertainment industry today.', 'unverified', 3);
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (9, 6, 25, 'No credible evidence supports this claim. The narrative is unfalsifiable by construction and has repeatedly been used to spread antisemitic conspiracy myths.', 1);
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (45, 28, 6, 9, 'refutes');
INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (7, 'chemtrail-claims', 'Chemtrail Claims', 'The belief that aircraft trails are secret spraying', 'Chemtrail claims assert that long-lasting trails behind aircraft are chemical or biological agents sprayed deliberately. Atmospheric science explains persistent trails as condensation trails (contrails). A 2016 survey of 77 experts found no evidence of a secret large-scale spraying program.', 'Aircraft engines emit water vapor and particles. In cold, humid air at cruising altitude this vapor condenses and freezes into ice crystals, forming contrails that can persist and spread into cirrus-like clouds.', 'Chemtrail claims spread in the late 1990s through talk radio and early internet forums and later via social media.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aircraft engines emit water vapor and particles. In cold, humid air at cruising altitude this vapor condenses and freezes into ice crystals, forming contrails that can persist and spread into cirrus-like clouds."}]},{"type":"paragraph","content":[{"type":"text","text":"Chemtrail claims spread in the late 1990s through talk radio and early internet forums and later via social media."}]}]}', 5, 'debunked', '/media/cards/technology.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:06');
