INSERT INTO theory_tags (theory_id, tag_id) VALUES (7, 28);
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (26, 7, 'Aircraft produce condensation trails that can persist and spread for hours when the upper atmosphere is cold and humid.', 'historically_documented', 0);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (46, 30, 7, 26, 'documents');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (27, 7, 'Persistent trails are chemicals sprayed deliberately as part of a secret large-scale program.', 'debunked', 1);
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (10, 7, 27, 'In a peer-reviewed survey, 76 of 77 atmospheric chemists and geochemists reported that they had not encountered evidence of a secret large-scale spraying program; alleged evidence could be explained by other factors.', 0);
INSERT INTO evidence (id, source_id, theory_id, counter_argument_id, relation) VALUES (47, 29, 7, 10, 'refutes');
INSERT INTO claims (id, theory_id, text, evidence_status, position) VALUES (28, 7, 'Solar geoengineering, such as injecting aerosols into the stratosphere, has been proposed in scientific literature.', 'historically_documented', 2);
INSERT INTO evidence (id, source_id, theory_id, claim_id, relation) VALUES (48, 31, 7, 28, 'documents');
INSERT INTO counter_arguments (id, theory_id, claim_id, text, position) VALUES (11, 7, 28, 'These are research proposals and assessments. No secret large-scale deployment is documented.', 1);
