INSERT INTO theories (id, slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published, created_at, updated_at) VALUES (8, 'jfk-related-conspiracy-narratives', 'JFK-related Conspiracy Narratives', 'Competing accounts of the 1963 assassination', 'President John F. Kennedy was assassinated in Dallas on 22 November 1963. The Warren Commission (1964) concluded that Lee Harvey Oswald acted alone. The House Select Committee on Assassinations (1979) concluded that Kennedy was probably assassinated as a result of a conspiracy, a finding based largely on acoustic evidence that the National Academy of Sciences disputed in 1982.', 'Oswald was arrested on the day of the assassination and shot dead two days later by Jack Ruby, so no trial took place. Gaps in the public record and long-classified files fuelled decades of alternative theories.', 'Critiques of the Warren Report appeared soon after 1964. Public interest grew after the HSCA findings and the 1991 film "JFK", which contributed to the JFK Records Act of 1992.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Oswald was arrested on the day of the assassination and shot dead two days later by Jack Ruby, so no trial took place. Gaps in the public record and long-classified files fuelled decades of alternative theories."}]},{"type":"paragraph","content":[{"type":"text","text":"Critiques of the Warren Report appeared soon after 1964. Public interest grew after the HSCA findings and the 1991 film \"JFK\", which contributed to the JFK Records Act of 1992."}]}]}', 1, 'disputed', '/media/cards/person.svg', 'Original illustration, The Conspiracy Atlas (see LICENSES.md)', 'editorial', 1, '2026-10-30 00:00:00', '2026-10-30 00:00:07');
