INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 1, 'de', 'text', 'Die Vereinigten Stabschefs sandten am 13. März 1962 ein Memorandum mit dem Titel „Justification for US Military Intervention in Cuba“ an den Verteidigungsminister.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 2, 'de', 'text', 'Die Vorschläge umfassten inszenierte Zwischenfälle, etwa einen vorgetäuschten Angriff auf ein US-Schiff, Kuba angelastete erfundene Vorfälle und einen inszenierten „Remember the Maine“-Zwischenfall.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 1, 'de', 'text', 'Kein Dokument und keine Aussage belegt, dass einer der Northwoods-Vorschläge umgesetzt wurde; die zivile Führung billigte sie nicht.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 3, 'de', 'text', 'Der Plan wurde genehmigt und ausgeführt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 2, 'de', 'text', 'Ein abgelehnter Vorschlag von 1962 ist kein Beleg für irgendein anderes Ereignis. Jede solche Behauptung braucht eigene, unabhängige Belege.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 4, 'de', 'text', 'Northwoods beweise, dass spätere Katastrophen von der US-Regierung inszenierte „False-Flag“-Operationen waren.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 1, 'de', 'title', 'Operation Northwoods');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 1, 'de', 'subtitle', 'Ein dokumentierter Vorschlag von 1962 für inszenierte Vorwände gegen Kuba');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 1, 'de', 'summary', 'Im März 1962 schlugen die Vereinigten Stabschefs der USA vor, Angriffe zu inszenieren oder vorzutäuschen, die Kuba angelastet werden könnten, um eine Militärintervention zu rechtfertigen. Der Vorschlag ist durch ein freigegebenes Memorandum belegt. Er wurde von der zivilen Führung nicht gebilligt und nie ausgeführt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 1, 'de', 'background', 'Nach der gescheiterten Invasion in der Schweinebucht (April 1961) übte die Regierung Kennedy im Rahmen der Operation Mongoose verdeckten Druck auf die kubanische Regierung aus. In diesem Zusammenhang leiteten die Stabschefs Verteidigungsminister Robert McNamara eine Reihe von Vorwand-Vorschlägen zu.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 5, 'de', 'text', 'Die CIA betrieb ein 1953 genehmigtes Forschungsprogramm mit dem Codenamen MKUltra, das Drogen wie LSD und andere Methoden der Verhaltensbeeinflussung untersuchte.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 6, 'de', 'text', 'Manchen Menschen wurden ohne ihr Wissen oder ihre Einwilligung Drogen verabreicht, darunter dem Wissenschaftler Frank Olson, der 1953 starb.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 7, 'de', 'text', 'Die meisten MKUltra-Akten wurden 1973 auf Anordnung von CIA-Direktor Richard Helms vernichtet.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 3, 'de', 'text', 'Erhaltene Unterlagen und offizielle Aussagen beschreiben Forschung mit begrenzten und uneinheitlichen Ergebnissen. Kein Dokument belegt, dass zuverlässige Gedankenkontrolle erreicht wurde.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 8, 'de', 'text', 'Die CIA habe zuverlässig „gedankengesteuerte“ Agenten erschaffen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 2, 'de', 'title', 'MKUltra');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 2, 'de', 'subtitle', 'Das verdeckte Forschungsprogramm der CIA zur Verhaltensbeeinflussung');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 2, 'de', 'summary', 'MKUltra war ein 1953 genehmigtes Forschungsprogramm der CIA, das Drogen und andere Methoden zur Beeinflussung menschlichen Verhaltens untersuchte, darunter Experimente an Menschen ohne deren Einwilligung. Seine Existenz wurde in den 1970er-Jahren durch offizielle Untersuchungen bestätigt. Die meisten Akten wurden 1973 vernichtet.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 2, 'de', 'background', 'Im frühen Kalten Krieg fürchteten US-Behörden, Gegner hätten Verhör- und „Gehirnwäsche“-Techniken entwickelt. Die CIA finanzierte Forschung an Universitäten, Kliniken und Gefängnissen, oft über Tarnorganisationen, im Rahmen mehrerer Projekte, von denen MKUltra das bekannteste ist.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 9, 'de', 'text', 'Am 17. Juni 1972 wurden fünf Männer in den Büros des Democratic National Committee im Watergate-Komplex festgenommen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 10, 'de', 'text', 'Die Einbrecher standen in Verbindung mit dem Committee for the Re-Election of the President.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 11, 'de', 'text', 'Präsident Nixon war an der Vertuschung beteiligt, wie das aufgezeichnete Gespräch vom 23. Juni 1972 (das „smoking gun“-Band) zeigt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 12, 'de', 'text', 'Der Oberste Gerichtshof ordnete in United States v. Nixon (1974) einstimmig die Herausgabe der Tonbänder an.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 13, 'de', 'text', 'Die vertrauliche Quelle „Deep Throat“ der Washington Post war der stellvertretende FBI-Direktor Mark Felt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 4, 'de', 'text', 'Diese revisionistischen Darstellungen sind umstritten, stützen sich auf strittige Aussagen und waren Gegenstand einer Verleumdungsklage des früheren Rechtsberaters des Weißen Hauses John Dean.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 14, 'de', 'text', 'Der Einbruch habe anderen, verborgenen Zwecken gedient und sei von anderen Insidern gesteuert worden.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 3, 'de', 'title', 'Watergate');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 3, 'de', 'subtitle', 'Eine dokumentierte politische Verschwörung, die eine Präsidentschaft beendete');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 3, 'de', 'summary', 'Der Einbruch in die Büros des Democratic National Committee im Watergate-Komplex 1972 und die anschließende Vertuschung führten im August 1974 zum Rücktritt von Präsident Richard Nixon. Watergate ist eine politische Verschwörung, die durch Gerichte, den Kongress und die aufgezeichneten Tonbänder des Weißen Hauses belegt ist.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 3, 'de', 'background', 'Im Präsidentschaftswahlkampf 1972 betrieben Personen aus dem Umfeld des Committee for the Re-Election of the President Spionage und Sabotage gegen politische Gegner. Die Festnahme von fünf Einbrechern am 17. Juni 1972 löste Ermittlungen durch Journalisten, einen Sonderermittler, eine Grand Jury und den Senat aus.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 15, 'de', 'text', 'Ein geheimes Testgelände am Groom Lake in Nevada wurde von CIA und Luftwaffe genutzt, um Aufklärungsflugzeuge wie die U-2 und die A-12 OXCART zu entwickeln und zu testen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 16, 'de', 'text', 'Die US-Regierung bestätigte das Gelände 2013 offiziell durch die Freigabe einer CIA-Geschichtsstudie.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 17, 'de', 'text', 'Geheime Höhenaufklärungsflüge erklären einen erheblichen Teil der UFO-Meldungen der 1950er- und 1960er-Jahre.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 5, 'de', 'text', 'Es wurden keine überprüfbaren Belege vorgelegt. Eine Untersuchung des US-Verteidigungsministeriums von 2024 fand keinen Hinweis darauf, dass ein Regierungsprogramm außerirdische Technologie besaß. Die angegebenen akademischen Abschlüsse des bekanntesten Zeugen ließen sich nicht bestätigen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 18, 'de', 'text', 'In oder bei Area 51 würden außerirdische Raumschiffe oder Wesen aufbewahrt oder untersucht.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 4, 'de', 'title', 'Area 51');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 4, 'de', 'subtitle', 'Ein realer geheimer Testort und die außerirdischen Behauptungen darum');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 4, 'de', 'summary', 'Area 51 am Groom Lake in Nevada ist eine reale, lange geheim gehaltene Testanlage, in der Aufklärungsflugzeuge wie die U-2 und die A-12 OXCART entwickelt wurden; ihre Existenz wurde 2013 offiziell bestätigt. Behauptungen, dort würden außerirdische Raumschiffe aufbewahrt oder untersucht, sind unbelegt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 4, 'de', 'background', '1955 wählten CIA und Luftwaffe den abgelegenen ausgetrockneten Salzsee Groom Lake als Testgelände für das Spionageflugzeug U-2. Auch spätere Programme wie die A-12 OXCART wurden dort erprobt. Die strikte Geheimhaltung förderte Spekulationen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 19, 'de', 'text', 'Apollo 11 landete am 20. Juli 1969 auf dem Mond und brachte die Besatzung sicher zur Erde zurück.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 6, 'de', 'text', 'Von Apollo-Besatzungen aufgestellte Reflektoren werden bis heute für Laser-Entfernungsmessungen genutzt, Mondproben wurden weltweit wissenschaftlich untersucht, und Orbitalkameras haben Landegeräte und Fußspuren fotografiert.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 20, 'de', 'text', 'Die Mondlandungen seien in einem Studio inszeniert worden.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 7, 'de', 'text', 'Kurze Belichtungszeiten für die helle Mondoberfläche erfassen keine schwachen Sterne; die Flagge hing an einer waagrechten Stange und bewegte sich nur bei Berührung; Schatten laufen wegen Perspektive und unebenem Gelände auseinander.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 21, 'de', 'text', 'Fotos zeigten Ungereimtheiten (keine Sterne, eine „wehende“ Flagge, nicht parallele Schatten), die eine Fälschung bewiesen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 5, 'de', 'title', 'Verschwörungstheorie zur Mondlandung');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 5, 'de', 'subtitle', 'Die Behauptung, die Apollo-Landungen seien gefälscht');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 5, 'de', 'summary', 'Die Behauptung, die NASA habe die Apollo-Mondlandungen (1969–1972) inszeniert, tauchte in den 1970er-Jahren auf. Ihr widersprechen umfangreiche unabhängige Belege, darunter zurückgebrachte Mondproben, noch heute für Laser-Entfernungsmessungen genutzte Reflektoren, unabhängige Verfolgung der Missionen und Orbitalaufnahmen der Landestellen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 5, 'de', 'background', 'Zwischen 1969 und 1972 brachten sechs Apollo-Missionen zwölf Astronauten auf den Mond. Das Programm fand während des Wettlaufs ins All mit der Sowjetunion statt, die die Missionen genau beobachtete.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 22, 'de', 'text', 'Der Illuminatenorden wurde am 1. Mai 1776 in Ingolstadt (Bayern) von Adam Weishaupt gegründet.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 23, 'de', 'text', 'Der Orden wurde durch Edikte des bayerischen Kurfürsten Karl Theodor 1784 und 1785 verboten.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 8, 'de', 'text', 'Historiker fanden keine Belege, dass der Orden nach dem Verbot aktiv blieb. Die Französische Revolution hat umfassend dokumentierte politische, soziale und wirtschaftliche Ursachen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 24, 'de', 'text', 'Die Illuminaten hätten heimlich überlebt und die Französische Revolution gesteuert.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 9, 'de', 'text', 'Keine glaubwürdigen Belege stützen diese Behauptung. Die Erzählung ist konstruktionsbedingt nicht widerlegbar und wurde wiederholt zur Verbreitung antisemitischer Verschwörungsmythen genutzt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 25, 'de', 'text', 'Die Illuminaten kontrollierten heute Regierungen, Finanzwelt oder Unterhaltungsindustrie.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 6, 'de', 'title', 'Illuminaten-Erzählungen');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 6, 'de', 'subtitle', 'Von einem bayerischen Geheimbund des 18. Jahrhunderts zum globalen Mythos');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 6, 'de', 'summary', 'Der Illuminatenorden war ein realer Geheimbund der Aufklärung, 1776 in Bayern gegründet und bis 1785 verboten. Behauptungen, er habe überlebt und lenke heimlich das Weltgeschehen, sind nicht belegt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 6, 'de', 'background', 'Adam Weishaupt, Professor an der Universität Ingolstadt, gründete den Orden, um Ideen der Aufklärung gegen den Einfluss von Kirche und Absolutismus zu fördern. Er warb unter der gebildeten Elite, teils über Freimaurerlogen, bevor Kurfürst Karl Theodor nicht genehmigte Geheimgesellschaften verbot.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 26, 'de', 'text', 'Flugzeuge erzeugen Kondensstreifen, die bei kalter und feuchter oberer Atmosphäre stundenlang bestehen und sich ausbreiten können.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 10, 'de', 'text', 'In einer begutachteten Umfrage gaben 76 von 77 Atmosphärenchemikern und Geochemikern an, keine Belege für ein geheimes großflächiges Sprühprogramm gefunden zu haben; angebliche Belege ließen sich anders erklären.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 27, 'de', 'text', 'Anhaltende Streifen seien Chemikalien, die im Rahmen eines geheimen großflächigen Programms absichtlich versprüht würden.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 11, 'de', 'text', 'Es handelt sich um Forschungsvorschläge und Bewertungen. Ein geheimer großflächiger Einsatz ist nicht dokumentiert.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 28, 'de', 'text', 'Solares Geoengineering, etwa das Einbringen von Aerosolen in die Stratosphäre, wurde in der Fachliteratur vorgeschlagen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 7, 'de', 'title', 'Chemtrail-Behauptungen');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 7, 'de', 'subtitle', 'Der Glaube, Kondensstreifen seien heimliches Sprühen');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 7, 'de', 'summary', 'Chemtrail-Behauptungen besagen, langlebige Streifen hinter Flugzeugen seien absichtlich versprühte chemische oder biologische Stoffe. Die Atmosphärenforschung erklärt anhaltende Streifen als Kondensstreifen. Eine Umfrage unter 77 Fachleuten fand 2016 keine Belege für ein geheimes großflächiges Sprühprogramm.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 7, 'de', 'background', 'Flugzeugtriebwerke stoßen Wasserdampf und Partikel aus. In kalter, feuchter Luft in Reiseflughöhe kondensiert und gefriert dieser Dampf zu Eiskristallen und bildet Kondensstreifen, die bestehen bleiben und sich zu zirrusartigen Wolken ausbreiten können.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 29, 'de', 'text', 'Kennedy wurde am 22. November 1963 auf der Dealey Plaza in Dallas erschossen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 30, 'de', 'text', 'Die Warren-Kommission kam zu dem Schluss, dass Lee Harvey Oswald die Schüsse abgab und allein handelte.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 31, 'de', 'text', 'Der HSCA folgerte 1979, Kennedy sei wahrscheinlich infolge einer Verschwörung ermordet worden.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 12, 'de', 'text', 'Der Ausschuss für ballistische Akustik der National Academy of Sciences kam 1982 zu dem Schluss, dass die akustischen Belege keinen Schuss vom Knoll zeigen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 32, 'de', 'text', 'Ein zweiter Schütze habe vom „Grassy Knoll“ aus geschossen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', 13, 'de', 'text', 'Keine offizielle Untersuchung hat dafür überprüfte Belege erbracht. Der HSCA stellte fest, dass CIA, FBI und Secret Service nicht beteiligt waren, konnte aber die Beteiligung einzelner Mitglieder bestimmter Gruppen nicht ausschließen.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', 33, 'de', 'text', 'Die CIA, das organisierte Verbrechen oder andere Gruppen hätten das Attentat geplant.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 8, 'de', 'title', 'Verschwörungserzählungen um JFK');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 8, 'de', 'subtitle', 'Konkurrierende Darstellungen des Attentats von 1963');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 8, 'de', 'summary', 'Präsident John F. Kennedy wurde am 22. November 1963 in Dallas ermordet. Die Warren-Kommission (1964) kam zu dem Schluss, dass Lee Harvey Oswald allein handelte. Der Untersuchungsausschuss des Repräsentantenhauses (HSCA, 1979) folgerte, Kennedy sei wahrscheinlich infolge einer Verschwörung ermordet worden – gestützt vor allem auf akustische Belege, die die National Academy of Sciences 1982 bestritt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', 8, 'de', 'background', 'Oswald wurde am Tag des Attentats festgenommen und zwei Tage später von Jack Ruby erschossen, sodass kein Prozess stattfand. Lücken im öffentlichen Archiv und lange geheime Akten nährten jahrzehntelang alternative Theorien.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('event', 1, 'de', 'title', 'Gründung des Illuminatenordens');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('event', 1, 'de', 'description', 'Adam Weishaupt gründet den Orden in Ingolstadt.');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('event', 2, 'de', 'title', 'Bayerische Edikte verbieten Geheimgesellschaften');
INSERT INTO translations (entity_type, entity_id, locale, field, value) VALUES ('event', 2, 'de', 'description', 'Kurfürst Karl Theodor verbietet nicht genehmigte Gesellschaften; das Edikt von 1785 nennt die Illuminaten.');
