INSERT INTO board_nodes (id, board_id, entity_type, entity_id, kind, title, summary, category_slug, evidence_status, image_path, tags_json, group_key) VALUES (1, 1, 'theory', 1, 'theory', 'Operation Northwoods', 'In March 1962 the U.S. Joint Chiefs of Staff proposed staging or simulating attacks that could be blamed on Cuba in order to justify a military intervention. The proposal is documented in a declassified memorandum. It was not approved by the civilian leadership and was never carried out.', 'secret-operations', 'historically_documented', '/media/cards/document.svg', '["Cold War","Cuba","Pentagon","False flag"]', 'secret-operations');
